head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[th > P > id]<br/>th 의 ID 를 설정합니다.",
    "validation" : [
        "th 를 구별할 수 있는 유일값을 문자열로 설정할 수 있어야 합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 table 있으면 삭제 (th 는 table 의 하위 요소이므로 table 을 삭제 후 재생성)
    if (typeof scwin.tbl1 !== 'undefined' && scwin.tbl1) {
        scwin.tbl1.remove();
    }

    $c.gcm.createLabel('label="[대상] 테이블 1행의 첫 번째 th (이름)\n[절차] ID 입력 -> Target 재생성\n[확인] getID 버튼으로 대상 th 의 ID 와 렌더링된 th 요소의 id 확인\n[참고] 예약어(예: scwin, $p, 기존 컴포넌트 ID) 입력 후 Target 재생성 시 생성 결과와 콘솔 오류 확인"', '', 'label1');

    // 조건 설정
    let cID = con_ID.getValue();

    // comp 생성 : 첫 번째 th 에 id 지정 (table id 는 tbl1 고정, 나머지 하위 요소는 공통 기본 id)
    scwin.tbl1 = await $c.gcm.createBasicTableLayout('', '', 'tbl1', '', { th: 'id="' + cID + '"' });
    scwin.target1 = scwin.tbl1._sub.th;
};



// validation 1, 2 판정 출력 : 대상 th 의 getID() 와 렌더링된 th 요소의 id
scwin.btn_getID_onclick = function (e) {
    let objTh = scwin.target1;

    if (!objTh) {
        wf_body_bottom.getObj("scwin").setReturnValue("대상 th 생성 결과 : " + objTh);
        return;
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getID() : " + objTh.getID() + " / th 요소 id : " + objTh.render.id);
};
